// Searchable list of places for Settings > Location: in India every district,
// well-known towns that are not district names, and two towns in each very wide
// district; abroad every country's capital, the major cities of Europe and the
// Americas, and cities where Indians commonly live or go. Pure data + matching;
// works offline. The data (coordinates and elevation) is generated by
// tools/build-india-places.py into india-places-data.js and by
// tools/build-world-places.py into world-places-data.js.
(function (global) {
  "use strict";
  const VedicEngine = global.VedicEngine = global.VedicEngine || {};
  const DATA = VedicEngine.IndiaPlacesData || { districts: [], towns: [] };
  const WORLD = VedicEngine.WorldPlacesData || { cities: [] };

  // Old / alternate spellings people still type -> the place they mean (by name).
  const ALIASES = {
    "Bengaluru Urban": ["Bangalore", "Bengaluru", "Bangalore Urban"], "Bengaluru Rural": ["Bangalore Rural"],
    "Mysuru": ["Mysore"], "Mangaluru": ["Mangalore"], "Hubballi": ["Hubli"], "Belagavi": ["Belgaum"],
    "Kalaburagi": ["Gulbarga"], "Ballari": ["Bellary"], "Vijayapura": ["Bijapur"], "Shivamogga": ["Shimoga"],
    "Tumakuru": ["Tumkur"], "Kochi": ["Cochin"], "Thiruvananthapuram": ["Trivandrum"], "Kozhikode": ["Calicut"],
    "Thrissur": ["Trichur"], "Alappuzha": ["Alleppey"], "Chennai": ["Madras"], "Tiruchirappalli": ["Trichy", "Tiruchchirappalli"],
    "Puducherry": ["Pondicherry", "Pondy"], "Thanjavur": ["Tanjore"], "Kanniyakumari": ["Kanyakumari", "Cape Comorin"],
    "Kanyakumari": ["Kanniyakumari", "Cape Comorin"], "Kolkata": ["Calcutta"], "Mumbai City": ["Bombay", "Mumbai"],
    "Mumbai Suburban": ["Bombay", "Mumbai"], "Pune": ["Poona"], "Prayagraj": ["Allahabad"], "Varanasi": ["Banaras", "Benares", "Kashi"],
    "Gurugram": ["Gurgaon"], "Vadodara": ["Baroda"], "Visakhapatnam": ["Vizag", "Vishakhapatnam"], "Kanpur Nagar": ["Cawnpore", "Kanpur"],
    "Ayodhya": ["Faizabad"], "Chhatrapati Sambhajinagar": ["Aurangabad"], "Aurangabad": ["Sambhajinagar"], "Osmanabad": ["Dharashiv"],
    "Ahmednagar": ["Ahilyanagar"], "Dharashiv": ["Osmanabad"], "Puri": ["Jagannath Puri"], "Rishikesh": ["Hrishikesh"],
    "Panaji": ["Panjim"], "Somnath": ["Veraval", "Prabhas Patan"], "Śṛṅgeri": ["Sringeri", "Shringeri", "Sringeri Sharada Peetham"],
    "Melukote": ["Melkote", "Melukote Cheluvanarayana"], "Hyderabad": ["Bhagyanagar"], "Gaya": ["Bodh Gaya", "Bodhgaya"],
    "Kutch": ["Kachchh", "Kachh", "Bhuj"], "Dwarka": ["Dwaraka"],
  };

  // Other names people type for a country (cities abroad also match on their country).
  const COUNTRY_ALTS = {
    "United States": ["USA", "US", "America", "United States of America"], "United Kingdom": ["UK", "Britain", "Great Britain", "England", "Scotland", "Wales"],
    "United Arab Emirates": ["UAE", "Emirates"], "Netherlands": ["Holland"], "Czechia": ["Czech Republic"], "Ivory Coast": ["Cote d'Ivoire"],
    "South Korea": ["Korea"], "North Korea": ["Korea"], "Russia": ["Russian Federation"], "Myanmar": ["Burma"], "Eswatini": ["Swaziland"],
    "Turkey": ["Turkiye"], "Vatican City": ["Holy See"], "North Macedonia": ["Macedonia"], "Timor-Leste": ["East Timor"],
    "Democratic Republic of the Congo": ["DR Congo", "DRC", "Congo"], "Republic of the Congo": ["Congo"], "Cape Verde": ["Cabo Verde"],
    "Palestine": ["West Bank"], "Taiwan": ["Republic of China"], "Laos": ["Lao"], "Bosnia and Herzegovina": ["Bosnia"],
    "Trinidad and Tobago": ["Trinidad", "Tobago"], "Antigua and Barbuda": ["Antigua"], "Saint Kitts and Nevis": ["St Kitts"],
    "Saint Vincent and the Grenadines": ["St Vincent"], "Saint Lucia": ["St Lucia"], "Sao Tome and Principe": ["Sao Tome"],
    "Papua New Guinea": ["PNG"], "Reunion": ["La Reunion"],
  };

  // Folds a spelling to a rough sound-alike key so Indian-name variants meet:
  // accents off, aa/ee/oo -> a/i/u, w -> v, y -> i, h dropped, doubled letters merged.
  function fold(s) {
    return String(s).normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase()
      .replace(/[^a-z ]+/g, " ").replace(/aa+/g, "a").replace(/(ee|ii)+/g, "i").replace(/(oo|uu)+/g, "u")
      .replace(/w/g, "v").replace(/y/g, "i").replace(/z/g, "j").replace(/h/g, "").replace(/(.)\1+/g, "$1")
      .replace(/\s+/g, " ").trim();
  }
  // Plain version: accents off, lower case, letters/digits/space only (used for exact and regex matching).
  function plain(s) {
    return String(s).normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/\s+/g, " ").trim();
  }

  const IST_ZONE = "Asia/Kolkata";
  const PLACES = [];
  DATA.towns.forEach(function (t) {
    // [name, district, state, lat, lon, elevation]
    PLACES.push({ name: t[0], state: t[2], district: t[1], kind: "town", latitude: t[3], longitude: t[4], elevation: t[5], timezone: IST_ZONE,
      label: t[0] + (t[1] ? ", " + t[1] + " district" : "") + ", " + t[2] });
  });
  DATA.districts.forEach(function (st) {
    st[1].forEach(function (d) {
      // [name, lat, lon, elevation]
      PLACES.push({ name: d[0], state: st[0], district: d[0], kind: "district", latitude: d[1], longitude: d[2], elevation: d[3], timezone: IST_ZONE,
        label: d[0] + " (district), " + st[0] });
    });
  });
  // [name, country, state/province or "", lat, lon, elevation, 1 if a capital, index into WORLD.zones, optional other spellings]
  // Capitals first, so a bare name typed for two cities (London) means the capital.
  WORLD.cities.slice().sort(function (a, b) { return b[6] - a[6]; }).forEach(function (c) {
    const title = c[0] === c[1] ? c[0] : c[0] + ", " + c[1];
    PLACES.push({ name: c[0], state: c[1], country: c[1], region: c[2], district: "", kind: "city", capital: !!c[6], latitude: c[3], longitude: c[4], elevation: c[5], timezone: WORLD.zones[c[7]] || IST_ZONE,
      title: title, label: c[0] === c[1] ? c[0] : c[0] + ", " + (c[2] ? c[2] + ", " : "") + c[1], extra: c[8] || [] });
  });
  // The name the top bar shows: the bare name, with the country when another place has the same name.
  const NAME_COUNT = {};
  PLACES.forEach(function (p) { const k = plain(p.name); NAME_COUNT[k] = (NAME_COUNT[k] || 0) + 1; });
  PLACES.forEach(function (p) {
    p.short = p.kind === "city" && NAME_COUNT[plain(p.name)] > 1 ? p.title : p.name;
    // The place's full name, as shown in lists and kept with a saved location.
    p.title = p.kind === "district" ? p.name + " (district)" : p.kind === "city" ? p.title : p.name;
    // The line under the name: "Texas, United States" / "Tiruvallur district, Tamil Nadu".
    p.where = p.kind === "city" ? (p.region ? p.region + ", " : "") + p.country : (p.kind === "town" && p.district ? p.district + " district, " : "") + p.state;
  });
  PLACES.forEach(function (p) {
    const alts = p.kind === "city" ? p.extra : (ALIASES[p.name] || []);
    p.plain = plain(p.label);
    p.fold = fold(p.name + " " + (p.kind === "town" ? p.district + " " : "") + (p.region ? p.region + " " : "") + p.state + " " + alts.join(" ") +
      (p.kind === "city" ? " " + (COUNTRY_ALTS[p.country] || []).join(" ") : ""));
    p.nameFold = fold(p.name);
    p.altFolds = alts.map(fold);
  });

  // The user typed a regular expression: /.../ , or any regex metacharacter.
  const REGEX_HINT = /^\/.+\/[i]?$|[\^$*+?|()[\]{}\\]/;
  function userRegex(query) {
    const m = /^\/(.+)\/i?$/.exec(query);
    try { return new RegExp(m ? m[1] : query, "i"); } catch (e) { return null; }
  }

  // Lower rank = better match; null = no match.
  function rank(p, tokens, subseq) {
    // A query of several words that is the whole name (or a spelling of it) beats words that merely turn up
    // in the district/state/country ("new york" is New York, not Albany in New York state).
    if (tokens.length > 1) {
      const whole = tokens.join(" ");
      if (p.nameFold === whole || p.altFolds.indexOf(whole) !== -1) return 0;
      if (p.nameFold.indexOf(whole) === 0) return 1;
    }
    let worst = 0;
    for (let i = 0; i < tokens.length; i++) {
      const t = tokens[i];
      let r;
      if (p.nameFold === t || p.altFolds.indexOf(t) !== -1) r = 0;
      else if (p.nameFold.indexOf(t) === 0 || p.altFolds.some(function (a) { return a.indexOf(t) === 0; })) r = 1;
      else if ((" " + p.fold).indexOf(" " + t) !== -1) r = 2;
      else if (p.fold.indexOf(t) !== -1) r = 3;
      else if (subseq && subseq.test(p.nameFold)) r = 4;
      else return null;
      if (r > worst) worst = r;
    }
    return worst;
  }

  // Best matches for what the user typed, best first.
  //  - "/^ra.*pur$/" or anything with regex symbols is used as a regular expression on the label;
  //  - otherwise every word typed must match (sound-alike folded, so "mysore", "banaras", "trichy",
  //    "dehradoon" or "pune maharashtra" all work), by name, alias, district or state;
  //  - a single word that matches nothing is tried as letters-in-order with small gaps ("pne" finds Pune).
  function search(query, limit) {
    const q = String(query || "").trim();
    if (!q) return [];
    limit = limit || 12;
    let hits;
    if (REGEX_HINT.test(q) && userRegex(q)) {
      const re = userRegex(q);
      // on the bare name (so ^ and $ mean the start/end of the name) or on the whole label
      hits = PLACES.filter(function (p) { return re.test(plain(p.name)) || re.test(p.plain); }).map(function (p) { return { p: p, r: 0 }; });
    } else {
      const tokens = fold(q).split(" ").filter(Boolean);
      if (!tokens.length) return [];
      hits = [];
      PLACES.forEach(function (p) {
        const r = rank(p, tokens, null);
        if (r !== null) hits.push({ p: p, r: r });
      });
      // Nothing matched: allow a typo - the letters in order from the same first letter, with at
      // most two other letters between each ("pne" finds Pune, "varansi" finds Varanasi).
      const letters = tokens.join("");
      if (!hits.length && tokens.length === 1 && letters.length >= 3) {
        const subseq = new RegExp("^" + letters.split("").join(".{0,2}"));
        PLACES.forEach(function (p) { if (subseq.test(p.nameFold)) hits.push({ p: p, r: 4 }); });
      }
    }
    // Same rank: India's towns, then its districts, then cities abroad (capitals first).
    const KIND_ORDER = { town: 0, district: 1, city: 2 };
    hits.sort(function (a, b) {
      return a.r - b.r || KIND_ORDER[a.p.kind] - KIND_ORDER[b.p.kind] || (b.p.capital ? 1 : 0) - (a.p.capital ? 1 : 0) || (a.p.label < b.p.label ? -1 : 1);
    });
    return hits.slice(0, limit).map(function (h) { return h.p; });
  }

  // Exact lookup by full label or bare name (accent- and case-insensitive).
  function find(text) {
    const t = plain(text);
    if (!t) return null;
    return PLACES.filter(function (p) { return p.plain === t; })[0] ||
      PLACES.filter(function (p) { return plain(p.name) === t; })[0] || null;
  }

  // The IANA time zone for a point: the listed place there, else the nearest listed place's.
  function timezoneAt(lat, lon) {
    const cosLat = Math.cos(lat * Math.PI / 180);
    let best = null, bd = Infinity;
    PLACES.forEach(function (p) {
      const dx = (p.longitude - lon) * cosLat, dy = p.latitude - lat, d = dx * dx + dy * dy;
      if (d < bd) { bd = d; best = p; }
    });
    return best ? best.timezone : IST_ZONE;
  }

  VedicEngine.IndiaPlaces = { PLACES: PLACES, find: find, search: search, fold: fold, timezoneAt: timezoneAt };
})(typeof window !== "undefined" ? window : globalThis);
